function countdown(id,seconds,onTick,onDone){const el=typeof id==='string'?document.getElementById(id):id;if(!el)return;clearInterval(timers[el.id]);let t=seconds;const draw=()=>{const m=String(Math.floor(t/60)).padStart(2,'0'),s=String(t%60).padStart(2,'0');el.textContent=`${m}:${s}`;if(onTick)onTick(t)};draw();timers[el.id]=setInterval(()=>{t--;draw();if(t<=0){clearInterval(timers[el.id]);if(onDone)onDone();}},1000);return ()=>{clearInterval(timers[el.id]);};}
function wordCount(text){return (text.trim().match(/\S+/g)||[]).length;}

function speakText(text,button,lang='en-GB'){if(!('speechSynthesis' in window)){alert('Audio playback is not supported in this browser.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=.95;u.onstart=()=>{if(button)button.disabled=true};u.onend=()=>{if(button)button.disabled=false};u.onerror=()=>{if(button)button.disabled=false};speechSynthesis.speak(u);}
