const guidedSentences=[
 {answer:'The client has approved the revised budget',words:['revised','approved','has','budget','the','client','the'],hint:'Start with the subject: The client. Then present perfect: has + past participle.',why:'Present perfect = subject + has/have + past participle + object.',a2:'The client | has approved | the revised budget.',b2:'Subject + present-perfect verb group + object: “The client has approved the revised budget.”'},
 {answer:'We should confirm the delivery date today',words:['today','confirm','should','date','we','delivery','the'],hint:'A modal is followed by the base verb.',why:'Modal structure: subject + should + base verb + object + time.',a2:'We | should confirm | the delivery date | today.',b2:'Keep “should confirm” together; the time expression naturally closes the sentence.'},
 {answer:'The meeting was moved to Friday afternoon',words:['Friday','was','the','afternoon','moved','meeting','to'],hint:'This is passive: subject + was + past participle.',why:'Passive past: The meeting + was moved + time destination.',a2:'The meeting | was moved | to Friday afternoon.',b2:'“Was moved” forms the passive; “to Friday afternoon” identifies the new time.'},
 {answer:'Did the supplier send the invoice yesterday',words:['invoice','did','yesterday','send','supplier','the','the'],hint:'Question: auxiliary + subject + base verb.',why:'After did, use base verb “send”, not “sent”.',a2:'Did | the supplier | send | the invoice | yesterday?',b2:'Past-simple question inversion places “did” before the subject and keeps “send” in base form.'},
 {answer:'We postponed the launch because testing was incomplete',words:['testing','the','because','launch','postponed','incomplete','we','was'],hint:'Build the main clause first, then add the reason clause.',why:'Main clause + because + subject + verb + complement.',a2:'We postponed the launch | because | testing was incomplete.',b2:'The causal connector links the decision to the reason without changing normal word order in the second clause.'},
 {answer:'The team will review the proposal tomorrow morning',words:['review','team','tomorrow','the','proposal','will','morning','the'],hint:'Future with will: subject + will + base verb.',why:'“Will review” stays together; the time phrase comes at the end.',a2:'The team | will review | the proposal | tomorrow morning.',b2:'Future auxiliary + base verb precedes the object; the specific time phrase closes the sentence.'},
 {answer:'Our manager asked us to update the schedule',words:['schedule','asked','our','to','us','manager','update','the'],hint:'Ask someone to do something = asked + object + to + verb.',why:'Verb pattern: asked us to update.',a2:'Our manager | asked us | to update | the schedule.',b2:'The reporting verb takes an object plus infinitive: “asked us to update”.'},
 {answer:'The new system is easier to use than the old one',words:['old','new','use','the','easier','system','than','to','one','is','the'],hint:'Comparative: is + comparative + than.',why:'“Easier to use than” is the comparative phrase.',a2:'The new system | is easier to use | than the old one.',b2:'The comparative adjective is followed by an infinitive complement and “than” comparison.'},
 {answer:'Please let me know if you need any further information',words:['information','let','need','me','please','further','if','know','you','any'],hint:'Polite request: Please let me know + if clause.',why:'Fixed business phrase: Please let me know if...',a2:'Please let me know | if you need | any further information.',b2:'The polite imperative is followed by an embedded conditional clause with normal statement word order.'}
];
