function shuffleWords(sentence,seed){const arr=sentence.replace(/[?.!]$/,'').split(' '),out=[...arr];let x=seed*9301+49297;for(let i=out.length-1;i>0;i--){x=(x*233280+49297)%233280;const j=x%(i+1);[out[i],out[j]]=[out[j],out[i]];}return out;}
function normalize(s){return s.trim().replace(/[?.!]$/,'').replace(/\s+/g,' ').toLowerCase();}
function sentenceBuilder(container,item,onChange){container.innerHTML='<div class="chip-bank"></div><div class="scramble-build"><span class="build-placeholder">Build the sentence here…</span></div>';const bank=$('.chip-bank',container),build=$('.scramble-build',container);let chosen=[];item.words.forEach((w,idx)=>{const b=document.createElement('button');b.type='button';b.className='word-chip';b.textContent=w;b.dataset.idx=idx;b.addEventListener('click',()=>{chosen.push({w,idx});b.classList.add('used');draw();if(onChange)onChange(chosen.map(x=>x.w).join(' '));});bank.appendChild(b)});function draw(){build.innerHTML='';if(!chosen.length){build.innerHTML='<span class="build-placeholder">Build the sentence here…</span>';return;}chosen.forEach((x,pos)=>{const t=document.createElement('button');t.type='button';t.className='build-token';t.textContent=x.w;t.title='Click to remove';t.addEventListener('click',()=>{chosen.splice(pos,1);bank.querySelector(`[data-idx="${x.idx}"]`).classList.remove('used');draw();if(onChange)onChange(chosen.map(y=>y.w).join(' '));});build.appendChild(t)});}return{get:()=>chosen.map(x=>x.w).join(' '),reset:()=>{chosen=[];$$('.word-chip',bank).forEach(x=>x.classList.remove('used'));draw();if(onChange)onChange('')}};}

