  let started=false;const startTimer=()=>{if(started)return;started=true;clearInterval(mInt);let t=45;const draw=()=>$('#mockTimer').textContent='00:'+String(t).padStart(2,'0');draw();mInt=setInterval(()=>{t--;draw();if(t<=0){clearInterval(mInt);submitMockItem();}},1000);};
