 function submitMockItem(){if(mState.submitted)return;clearInterval(mInt);const text=mBuilder.get(),ok=normalize(text)===normalize(mockSentences[mState.idx].answer);mState.answers[mState.idx]={text,ok};if(mState.idx<8){mState.idx++;localStorage.setItem(mKey,JSON.stringify(mState));renderMock();}else{mState.submitted=true;localStorage.setItem(mKey,JSON.stringify(mState));series.lessons['4']={...(series.lessons['4']||{}),skill:'Writing',screening:{correct:sentenceStats(mockSentences,mState.answers).correct,total:9,percent:sentenceStats(mockSentences,mState.answers).percent},completed:false};saveSeries();renderMock();}}
