function sentenceStats(items,answers){let correct=0,answered=0;items.forEach((x,i)=>{if(answers[i]){answered++;if(answers[i].ok)correct++;}});return{correct,answered,total:items.length,percent:Math.round(correct/items.length*100)}}

// ---------- RUBRIC UTILITIES ----------
const rubricCriteria=[['Task completion','Covers every bullet and stays relevant.'],['Organization','Ideas are logically ordered and easy to follow.'],['Grammar control','Sentence structures and verb forms are controlled.'],['Vocabulary & clarity','Word choice is appropriate and meaning is clear.'],['Accuracy & proofreading','Spelling, punctuation and simple errors are checked.']];
function buildRubric(containerId,key,onUpdate){const box=$(containerId);if(!box)return;const saved=readJSON(key,{});box.innerHTML='';rubricCriteria.forEach(([name,desc],i)=>{const row=document.createElement('div');row.className='rubric-row';row.innerHTML=`<div class="rubric-label"><strong>${name}</strong><small>${desc}</small></div>`;for(let n=0;n<=5;n++){const lab=document.createElement('label');lab.innerHTML=`<input type="radio" name="${key}_${i}" value="${n}" ${Number(saved[i])===n?'checked':''}>${n}`;row.appendChild(lab)}box.appendChild(row)});$$(`input[name^="${key}_"]`,box).forEach(inp=>inp.addEventListener('change',()=>{const i=Number(inp.name.split('_').pop());saved[i]=Number(inp.value);localStorage.setItem(key,JSON.stringify(saved));if(onUpdate)onUpdate(saved);}));if(onUpdate)onUpdate(saved);return saved;}
function rubricStats(saved){const vals=[0,1,2,3,4].filter(i=>Object.prototype.hasOwnProperty.call(saved,i)).map(i=>Number(saved[i])),sum=vals.reduce((a,b)=>a+b,0),complete=vals.length===5;return{sum,total:25,percent:Math.round(sum/25*100),complete};}

// ---------- 4C ESSAY MASTERY ----------
if(page==='essay'){
 const modelText={a2:`I think using a project-management tool can be useful for a team. First, it gives everyone the same information about tasks and deadlines. For example, employees can see what is finished and what still needs to be done. However, some people may find the new system difficult at first, especially if they are not comfortable with technology. I think the company should organize a short practical training session and give employees a simple guide. A colleague could also be available to answer questions during the first weeks. This would help people feel more confident and use the tool correctly.`,b2:`Introducing a digital project-management tool can improve visibility and coordination because team members can follow responsibilities, deadlines and progress in one place. The main difficulty is likely to be adoption: employees who are comfortable with existing routines may see the new platform as additional work rather than a useful resource. I would therefore recommend a short hands-on training session using realistic projects, followed by simple written guidance and accessible support during the first few weeks. Managers should also explain why the tool is being introduced and agree on clear rules for updating tasks. This combination of practical training and consistent expectations would make the transition smoother and reduce duplicated work.`};
 $('#essayModel').textContent=modelText.a2;$$('[data-model-level]').forEach(b=>b.addEventListener('click',()=>{$$('[data-model-level]').forEach(x=>x.classList.toggle('active',x===b));$('#essayModel').textContent=modelText[b.dataset.modelLevel];}));
 const writingVocab={
  opinion:[['In my view','à mon avis','In my view, the new system would improve coordination.'],['I believe','je pense / je crois','I believe practical training is essential.'],['From my perspective','de mon point de vue','From my perspective, flexibility can improve motivation.']],
  develop:[['for example','par exemple','For example, a shared dashboard can reduce duplicated work.'],['in addition','de plus','In addition, managers should provide clear guidance.'],['as a result','par conséquent','As a result, employees may adapt more quickly.']],
  contrast:[['however','cependant','However, the change may create difficulties at first.'],['although','bien que','Although the system is useful, some employees may need support.'],['on the other hand','d’un autre côté','On the other hand, remote work can make communication harder.']],
  recommend:[['I would recommend','je recommanderais','I would recommend a short trial period.'],['should','devrait / devraient','Managers should explain the purpose of the change.'],['could','pourrait / pourraient','The company could organize practical workshops.']]
 };
 let writeAccent='en-GB';
 function renderWritingVocab(cat){const grid=$('#writingVocabGrid');if(!grid)return;grid.innerHTML='';writingVocab[cat].forEach(v=>{const d=document.createElement('div');d.className='vocab-card';d.innerHTML=`<div class="vocab-card-head"><div><h4>${v[0]}</h4><span class="fr">${v[1]}</span></div><button class="audio-mini" type="button">▶ AUDIO</button></div><p>${v[2]}</p>`;$('.audio-mini',d).addEventListener('click',e=>speakText(`${v[0]}. ${v[2]}`,e.currentTarget,writeAccent));grid.appendChild(d)});}
 if($('#writingVocabTabs')){const tabs=$('#writingVocabTabs');Object.keys(writingVocab).forEach((cat,i)=>{const b=document.createElement('button');b.type='button';b.textContent=cat.toUpperCase();b.classList.toggle('active',i===0);b.addEventListener('click',()=>{$$('#writingVocabTabs button').forEach(x=>x.classList.toggle('active',x===b));renderWritingVocab(cat)});tabs.appendChild(b)});const sel=document.createElement('select');sel.className='compact-select';sel.innerHTML='<option value="en-GB">🇬🇧 British audio</option><option value="en-US">🇺🇸 American audio</option>';sel.addEventListener('change',()=>writeAccent=sel.value);tabs.appendChild(sel);renderWritingVocab(Object.keys(writingVocab)[0]);}
 const essayLabs=[
  {tab:'Past experience',title:'Describe a time you had to work with someone very different from you.',bullets:['who the person was','how you were different','how you managed the situation'],plan:['colleague from another department','different communication styles / direct vs detailed','short check-ins + written summary'],a2:'I once worked with a colleague from another department who had a very different way of communicating. I liked short and direct messages, but he preferred long explanations and detailed meetings. At first, this caused some confusion because we sometimes understood priorities differently. To manage the situation, we agreed to have a short meeting every morning and then send a written summary of the decisions. This helped both of us because we knew exactly what to do. In the end, the project went well and I learned that adapting your communication style can make teamwork much easier.',b2:'During a cross-department project, I worked closely with a colleague whose communication style was almost the opposite of mine. I tend to prefer concise updates and quick decisions, whereas he wanted to examine every detail before moving forward. Initially, this difference slowed us down and occasionally created misunderstandings about priorities. We solved the problem by combining our approaches: we held brief daily check-ins for urgent decisions and followed them with a written summary containing responsibilities and deadlines. This gave him the detail he needed without making every discussion unnecessarily long. The experience taught me that effective collaboration often depends less on having the same working style than on agreeing a communication method that works for everyone.'},
  {tab:'Problem → solution',title:'Your team has missed several important deadlines.',bullets:['one reason this may be happening','the impact on clients or colleagues','what the manager should change'],plan:['priorities not clear / too many urgent tasks','late client information + team stress','weekly priorities + owners + realistic deadlines'],a2:'There may be several reasons why a team misses deadlines, but one common problem is that priorities are not clear. Employees can receive many urgent requests at the same time and may not know which task should come first. This can create stress for the team and can also affect clients if they receive information or deliveries late. I think the manager should create a clear weekly priority list and make sure every important task has one person responsible for it. Short progress meetings could also help the team identify problems earlier. This would make deadlines more realistic and communication clearer.',b2:'Repeated missed deadlines often indicate a planning problem rather than a lack of effort. One possible cause is that priorities are constantly changing, leaving employees unsure which requests are genuinely urgent. The result can be duplicated work, increased stress and delayed responses to clients. I would recommend introducing a short weekly planning meeting in which the team agrees the three main priorities, assigns clear ownership and identifies any dependencies that could create delays. Managers should also review workload before accepting unrealistic deadlines. This approach would improve visibility and allow risks to be addressed before they affect the customer.'},
  {tab:'Recommendation',title:'Your company wants to improve training for new employees.',bullets:['what new employees need first','which training format you recommend','how the company could check whether it works'],plan:['role + systems + key contacts','workshop + job shadowing + guide','feedback after 2 weeks + manager check'],a2:'New employees first need to understand their role, the main systems they will use and who they can ask for help. I would recommend a mixed training programme. They could start with a short practical workshop, then spend time with an experienced colleague. A simple written guide would also be useful because they could check information later. To see if the training works, the company could ask new employees for feedback after two weeks and organize a short meeting with their manager. This would help the company identify any missing information and improve the programme.',b2:'Effective onboarding should give new employees both essential information and the confidence to apply it in real situations. I would therefore recommend a blended approach: a concise introductory workshop for key procedures, structured job shadowing with an experienced colleague, and a searchable guide for reference after the formal training ends. To evaluate the programme, the company could combine a short learner survey after two weeks with a manager review after the first month. Comparing confidence, common questions and early performance would provide useful evidence about which parts of the training need to be strengthened.'},
  {tab:'Change management',title:'Your company is introducing new software across several teams.',bullets:['one benefit of the change','one risk or difficulty','how managers should introduce it'],plan:['shared data / fewer duplicate files','resistance + learning curve','pilot + practical training + support'],a2:'New software can be useful because it can put information in one place and reduce duplicated files. However, some employees may find the change difficult, especially if they are comfortable with the old system. They may also worry that the new tool will take more time. I think managers should introduce the software gradually. First, a small group could test it. Then the company should organize practical training with real examples and provide support during the first weeks. Managers should also explain why the change is necessary. This would help employees understand the benefits and feel more confident.',b2:'Introducing a shared software platform could improve coordination by centralizing information and reducing duplicated work across teams. The main risk is adoption: if employees see the new system as an additional administrative burden, they may continue using old tools in parallel, which would undermine the benefits. Managers should therefore treat the rollout as a change-management project rather than simply a technical installation. A pilot group could test the workflow, practical training should use realistic tasks, and accessible support should remain available during the transition. Clear communication about the purpose of the change would also help build commitment.'},
  {tab:'Teamwork',title:'Some employees prefer working independently while others prefer teamwork.',bullets:['one advantage of independent work','one advantage of teamwork','when teamwork is essential'],plan:['focus / speed on individual tasks','share ideas / solve complex problems','projects with dependencies / customer issues'],a2:'Working independently can be useful because people can concentrate without interruptions and organize their own time. Teamwork also has important advantages because colleagues can share ideas and help each other solve problems. In my opinion, teamwork is especially important when a project has several connected tasks or when a difficult customer problem requires different types of knowledge. A good company should use both methods. Employees can work alone when they need concentration, but they should communicate regularly and work together when decisions affect other people.',b2:'Independent work can increase concentration and efficiency, particularly for tasks that require deep focus or individual expertise. Teamwork, by contrast, is valuable when a problem benefits from several perspectives or when responsibilities are closely connected. Collaboration becomes essential on projects with strong dependencies, during complex customer issues, or when a decision will affect several departments. Rather than treating one approach as universally better, organizations should create clear expectations about when employees can work autonomously and when active coordination is required. The most effective teams usually combine individual responsibility with purposeful collaboration.'},
  {tab:'Customer service',title:'Customer complaints have increased during the last month.',bullets:['one possible cause','how the company should respond now','one long-term improvement'],plan:['response times increased','acknowledge + prioritize + update customers','track complaint categories + process/staffing review'],a2:'One possible reason for the increase in complaints is that customers are waiting too long for answers. The company should respond quickly by acknowledging every complaint and giving customers a clear update about when they will receive a solution. Urgent cases should be prioritized. For the long term, I think the company should record the main reasons for complaints and review them every month. If many problems are caused by slow responses, the company may need more staff or a better system for assigning requests. This would help solve the cause of the problem, not only individual complaints.',b2:'A sudden increase in complaints may indicate that response times or service consistency have deteriorated. The immediate priority should be to acknowledge outstanding cases, categorize them by urgency and give customers realistic update times rather than leaving them without information. Longer term, the company should analyse complaint categories, response-time data and workload patterns to identify the underlying cause. If delays are concentrated at particular stages, the process may need redesign; if the issue is capacity, staffing or scheduling may need adjustment. Combining short-term recovery with systematic analysis would protect customer trust while preventing the same problems from recurring.'}
 ];
 const labNotesKey=BASE+'EssayLabNotes',labNotes=readJSON(labNotesKey,{});let activeLab=0;
 const essayModelExtensions=[
  {b1:`I once worked with a colleague from another department. We had different communication habits: I liked short updates, but he wanted detailed explanations. This sometimes created confusion about our priorities. To improve the situation, I suggested a quick meeting each morning. We also wrote a summary after each meeting, so both of us knew who was responsible for each task. For example, when a deadline changed, we could check the summary instead of discussing everything again. As a result, we worked more efficiently and completed the project successfully. This experience taught me that listening and agreeing on a clear method can improve teamwork.`,c1:`A cross-department assignment taught me that differences in working style need not become an obstacle to collaboration. While I favour concise updates and prompt decisions, my colleague preferred extensive analysis before committing to a course of action. The resulting misunderstandings initially affected our ability to prioritise tasks. Rather than asking either person to abandon their approach, we introduced short daily decision meetings supported by written summaries of responsibilities and deadlines. This arrangement preserved the detail he valued while ensuring that urgent questions were resolved quickly. As coordination improved, we delivered the project on schedule. The experience reinforced a broader lesson: effective teamwork relies on adapting processes to different people, not expecting everyone to communicate identically.`},
  {b1:`Our team has missed several deadlines recently. I think the main reason is that employees receive too many urgent tasks and do not always know which one to do first. This situation causes stress and may also disappoint customers who are waiting for information. For example, a client might receive an important report two days late. I would recommend a short planning meeting every Monday. The manager could agree on priorities, name the person responsible for each task and check whether the deadlines are realistic. A second short meeting during the week would help us identify problems early. As a result, we could reduce delays and communicate more clearly with clients.`,c1:`Persistent missed deadlines often reflect weaknesses in prioritisation and workload management rather than a lack of commitment. When successive urgent requests arrive without clear ownership, employees may duplicate effort or overlook dependencies. This not only increases internal pressure but can damage clients’ confidence when promised information arrives late. I would recommend introducing a weekly planning cycle in which the team identifies critical deliverables, assigns accountable owners and explicitly flags potential bottlenecks. Managers should also challenge unrealistic commitments before they are communicated externally. Progress could be reviewed midweek, with any emerging risk raised promptly rather than concealed until a deadline has passed. Such a system would make delivery more predictable while improving both staff wellbeing and customer communication.`},
  {b1:`When new employees join a company, they need to understand their daily responsibilities, the tools they will use and the people who can help them. I would recommend combining a short introduction with practical training. For example, a new colleague could attend a workshop in the morning and then observe an experienced employee during a real task. A simple guide with useful contacts would also help them when they have questions later. After two weeks, the manager should ask each employee what was useful and what was missing. The company could use these answers to improve the programme. This would help new employees feel confident and become independent more quickly.`,c1:`An onboarding programme should equip newcomers not merely with information but with the confidence to perform their responsibilities independently. Essential priorities include a clear understanding of the role, access to core systems and knowledge of where to seek support. I would recommend a blended programme combining concise introductory sessions, supervised practice and structured job shadowing, supplemented by a searchable reference guide. Rather than overwhelming recruits on their first day, training could be phased according to the tasks they actually need to perform. Effectiveness should be assessed through brief feedback surveys, manager check-ins and practical demonstrations after two and six weeks. These measures would reveal whether knowledge is being applied, allowing the organisation to refine its approach based on evidence rather than assumptions.`},
  {b1:`Our company is introducing a new way of working, and this may change some employees’ daily tasks. One advantage is that the new system could save time and make information easier to find. However, some colleagues may feel worried because they are comfortable with the old process. I think managers should explain the reason for the change before it begins. They could also organise practical training and ask employees for feedback. For example, a small group could test the system first and share useful advice. As a result, the company could solve problems early and help the rest of the team adapt more easily.`,c1:`Introducing a new working process can improve consistency and reduce repetitive tasks, but its success will depend on how effectively employees are supported through the transition. Even a well-designed system may meet resistance when colleagues feel that their expertise or established routines are being overlooked. Management should therefore communicate the purpose of the change, outline its expected benefits and acknowledge legitimate concerns. I would propose a phased implementation, beginning with a representative pilot group and practical training sessions. Feedback collected during the trial should inform adjustments before a wider launch. By involving employees in the process and measuring both adoption and operational outcomes, the organisation could reduce disruption and build lasting confidence in the new approach.`},
  {b1:`Good teamwork is important when several people share a project. One possible difficulty is that team members do not always know what others are doing. This can cause mistakes or delays, especially when employees work in different departments. I think the team should agree on clear roles and hold short regular meetings. For example, every Friday each person could explain what they have finished and what they need help with. A shared task list would make responsibilities easier to see. These simple changes could improve communication and reduce misunderstandings. They would also help employees feel that their work is valued.`,c1:`A productive team needs more than individual competence; it requires shared expectations, transparent responsibilities and the ability to raise concerns early. When several departments contribute to the same project, information can become fragmented and important decisions may be delayed. I would recommend assigning clear ownership for each deliverable, maintaining a shared task board and holding brief, purposeful coordination meetings. These meetings should focus on obstacles and dependencies rather than lengthy status reports. For example, a potential delay identified by one department could trigger an immediate adjustment to another team’s schedule. Combining reliable processes with an open communication culture would strengthen accountability, prevent avoidable duplication and ultimately improve the quality of collaborative work.`},
  {b1:`A customer recently complained because an important order arrived late. I understand why this was frustrating, especially because the customer needed the product for a planned event. First, the company should apologise clearly and explain what happened without making excuses. Then, it should offer a realistic new delivery date and regular updates. For example, one employee could contact the customer every day until the order arrives. I would also recommend checking with the delivery team to understand why the delay happened. This could help the company avoid the same problem in the future. Good communication is important because it can rebuild the customer’s trust.`,c1:`When an important delivery is delayed, the immediate priority is to recognise the impact on the customer and provide reliable information rather than vague reassurance. The company should acknowledge the disruption, apologise without shifting responsibility and confirm a revised delivery date only after checking the relevant logistics. A dedicated contact person could provide proactive updates until the matter is resolved, with an appropriate alternative offered if the original deadline can no longer be met. Alongside the immediate response, managers should investigate the root cause and identify whether planning, stock visibility or communication contributed to the failure. Addressing both the individual complaint and the underlying process would demonstrate accountability and help restore confidence while reducing the likelihood of recurrence.`}
 ];
 const essayLevelWhy={a2:'A2: clear, mostly short sentences. Check that all three points are present; the next step is to add a reason and concrete example.',b1:'B1: each point is explained with because, for example or as a result. The next step is more precise links and evaluation.',b2:'B2: more specific workplace vocabulary, analysed consequences, contrasts and developed recommendations.',c1:'C1: deliberate organisation, nuanced reasoning, controlled complex grammar and practical evaluation; clarity still matters.'};
 function renderEssayLab(){
  const item=essayLabs[activeLab],box=$('#promptLab');if(!box)return;
  $$('#promptLabTabs button').forEach((b,i)=>b.classList.toggle('active',i===activeLab));
  const saved=labNotes[activeLab]||{};
  const safe=x=>String(x??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  box.innerHTML=`<div class="prompt-lab-head"><span>SUBJECT ${activeLab+1} / ${essayLabs.length} · IDENTICAL TASK FOR A2 / B1 / B2 / C1</span><h3>${safe(item.title)}</h3><p><strong>Write about all three points:</strong></p><ol>${item.bullets.map(x=>`<li>${safe(x)}</li>`).join('')}</ol></div>
   <div class="plan-workbench"><div class="workshop-steps-intro"><strong>FIRST: complete your own four-step plan.</strong><p>Do not write the full essay yet. For each bullet, write a keyword, a reason and a specific workplace example. Your answers save automatically.</p></div>
   <div class="plan-steps"><label>01 · WHAT IS THE TASK?<small>What situation or opinion must you address?</small><textarea data-lab-field="task" placeholder="Example: Explain the change and recommend support…">${safe(saved.task)}</textarea></label>${item.bullets.map((x,i)=>`<label>0${i+2} · BULLET ${i+1}: ${safe(x)}<small>Point + because + realistic example</small><textarea data-lab-field="b${i}" placeholder="My key idea → reason → example">${safe(saved['b'+i])}</textarea></label>`).join('')}</div>
   <div class="plan-actions"><button class="primary" id="checkLabPlan" type="button">CHECK MY FOUR-STEP PLAN</button><button class="secondary coach-only" id="labHint" type="button">HINT FOR THIS SUBJECT</button><button class="secondary coach-only" id="showPlanModel" type="button">SHOW MODEL PLAN</button></div>
   <p id="labPlanFeedback" class="plan-feedback" role="status" aria-live="polite">Write the four steps, then check whether every bullet has a clear idea.</p><div class="plan-model hidden coach-only" id="labHintOut"></div><div class="plan-model hidden coach-only" id="labPlanModel"></div>
   <div class="workshop-stage inline-model-stage coach-only"><span class="stage-number">STEP 3</span><div><strong>Reveal the complete essay for THIS subject</strong><p>Open A2, B1, B2 or C1 below. Compare two levels and identify what improves. The subject and three bullets stay visible above.</p></div></div>
   <div class="plan-actions coach-only">${['a2','b1','b2','c1'].map(level=>`<button class="secondary" data-lab-model="${level}" type="button">${level.toUpperCase()} · FULL ESSAY</button>`).join('')}</div><div class="essay-model hidden coach-only" id="labEssayModel"></div></div>`;
  $$('[data-lab-field]',box).forEach(el=>el.addEventListener('input',()=>{labNotes[activeLab]??={};labNotes[activeLab][el.dataset.labField]=el.value;localStorage.setItem(labNotesKey,JSON.stringify(labNotes));}));
  $('#checkLabPlan').addEventListener('click',()=>{const fields=$$('[data-lab-field]',box),filled=fields.filter(x=>x.value.trim().length>=8).length;const missing=fields.filter(x=>x.value.trim().length<8).map((x,i)=>x.closest('label').textContent.trim().split('·')[0].trim());const status=$('#labPlanFeedback');status.textContent=filled===4?'✓ Four plan steps completed. Now check that each bullet has a reason or specific example; the A2–C1 models are directly below.':`Plan: ${filled}/4 steps contain a usable idea. Add information to ${4-filled} step(s). A keyword alone is not yet a reason or example.`;status.className='plan-feedback '+(filled===4?'correct':'needs-work');});
  $('#labHint').addEventListener('click',()=>{const out=$('#labHintOut');out.classList.toggle('hidden');out.textContent=`SUGGESTED IDEAS (not sentences to copy):\n• ${item.plan[0]}\n• ${item.plan[1]}\n• ${item.plan[2]}`;});
  $('#showPlanModel').addEventListener('click',()=>{const m=$('#labPlanModel');m.classList.toggle('hidden');m.textContent=`MODEL 1-MINUTE PLAN\nTask: ${item.title}\n1 · ${item.bullets[0]} → ${item.plan[0]}\n2 · ${item.bullets[1]} → ${item.plan[1]}\n3 · ${item.bullets[2]} → ${item.plan[2]}\nClosing: explain the practical result or lesson learned.`;});
  $$('[data-lab-model]',box).forEach(b=>b.addEventListener('click',()=>{const m=$('#labEssayModel'),level=b.dataset.labModel,model=essayModelExtensions[activeLab][level]||item[level];$$('[data-lab-model]',box).forEach(x=>x.classList.toggle('active',x===b));m.classList.remove('hidden');m.innerHTML=`<span class="mini-label">${level.toUpperCase()} MODEL · SUBJECT ${activeLab+1}</span><h4>${safe(item.title)}</h4><p class="model-subject-bullets">${item.bullets.map((x,i)=>`${i+1}. ${safe(x)}`).join(' · ')}</p><div class="model-essay-paragraph">${safe(model)}</div><div class="model-why"><strong>Why this level earns more marks in a training rubric</strong><p>${safe(essayLevelWhy[level])}</p></div>`;}));
 }
 if($('#promptLabTabs')){essayLabs.forEach((x,i)=>{const b=document.createElement('button');b.type='button';b.textContent=x.tab;b.addEventListener('click',()=>{activeLab=i;renderEssayLab()});$('#promptLabTabs').appendChild(b)});renderEssayLab();}
 $('#startPrep').addEventListener('click',()=>countdown('prepTimer',60));
 const essayKey=BASE+'PracticeEssay',ta=$('#practiceEssay');ta.value=localStorage.getItem(essayKey)||'';function wc(){const n=wordCount(ta.value);$('#practiceWordCount').textContent=`${n} word${n===1?'':'s'}`;localStorage.setItem(essayKey,ta.value);updateEssayCenter();}ta.addEventListener('input',wc);
 $('#essayHintBtn').addEventListener('click',()=>$('#essayHint').classList.toggle('hidden'));$('#startEssay').addEventListener('click',()=>countdown('essayTimer',1200,()=>{},()=>{ta.disabled=true;$('#startEssay').textContent='TIME COMPLETE';}));
 const rubricKey=BASE+'PracticeRubric';let practiceRubric={};practiceRubric=buildRubric('#practiceRubric',rubricKey,()=>updateEssayCenter());
 function updateEssayCenter(){practiceRubric=readJSON(rubricKey,{});const st=rubricStats(practiceRubric),n=wordCount(ta.value);$('#rubricScore').textContent=`${st.sum}/25`;$('#rubricPercent').textContent=`${st.percent}%`;$('#essayPracticeScore').textContent=`${st.sum}/25`;$('#essayPracticePercent').textContent=`${st.percent}%`;$('#essayTitle').textContent=st.complete?(st.percent>=80?'Strong Practice Essay. Ready for the Final Mock.':st.percent>=60?'Good base. Review the lower-scored criterion before the Final Mock.':'Repeat the essay method before the Final Mock.'):'Write the practice essay, then complete all five rubric criteria.';$('#essayText').textContent=`Word count: ${n}. Rubric completed: ${Object.keys(practiceRubric).length}/5 criteria. Practice score: ${st.sum}/25 (${st.percent}%).`;series.lessons['4']={...(series.lessons['4']||{}),skill:'Writing',practiceEssay:{score:st.sum,total:25,percent:st.percent,words:n,complete:st.complete},completed:false};saveSeries();}
 wc();updateEssayCenter();
 $('#downloadResults').addEventListener('click',()=>{const st=rubricStats(readJSON(rubricKey,{})),n=wordCount(ta.value);download('vtest_lesson_4C_essay_practice.txt',`VTEST BUSINESS ENGLISH · LESSON 4C · ESSAY MASTERY\n\nPractice Essay rubric: ${st.sum}/25 (${st.percent}%)\nRubric complete: ${st.complete?'yes':'no'}\nWord count: ${n}\n\nThis is a transparent trainer rubric, not the official VTest scoring algorithm.\n`)});
 $('#resetBtn').addEventListener('click',()=>{if(confirm('Reset Lesson 4C essay practice and rubric?')){[essayKey,rubricKey,sectionKey].forEach(k=>localStorage.removeItem(k));if(series.lessons['4'])delete series.lessons['4'].practiceEssay;saveSeries();location.reload();}});
}

