 const sKey=BASE+'FinalScreen',sState=readJSON(sKey,{idx:0,answers:{},submitted:false});let sBuilder=null,sInt=null;
 function renderFinalScreen(){
  if(sState.submitted){const st=sentenceStats(finalScreenSentences,sState.answers);$('#finalScreenStage').innerHTML=`<div class="sim-report"><h2>Pre-Writing screening complete · ${st.correct}/9 correct</h2><p>This score is saved separately. Continue to the essay.</p></div>`;$('#finalScreenNext').disabled=true;$('#finalScreenPrev').disabled=true;updateFinalCenter();return;}
  const item=finalScreenSentences[sState.idx];$('#finalScreenCounter').textContent=`Sentence ${sState.idx+1} / 9`;$('#finalScreenBar').style.width=`${(sState.idx+1)/9*100}%`;$('#finalScreenTimer').textContent='00:45';$('#finalScreenStage').innerHTML='<div id="fsBuilder"></div><div class="practice-counter">Timer starts with your first selected word.</div>';
  let started=false;const startTimer=()=>{if(started)return;started=true;clearInterval(sInt);let t=45;const draw=()=>$('#finalScreenTimer').textContent='00:'+String(t).padStart(2,'0');draw();sInt=setInterval(()=>{t--;draw();if(t<=0){clearInterval(sInt);submitFinalScreen();}},1000);};
  sBuilder=sentenceBuilder($('#fsBuilder'),item,()=>startTimer());
 }
 function submitFinalScreen(){if(sState.submitted)return;clearInterval(sInt);const text=sBuilder.get(),ok=normalize(text)===normalize(finalScreenSentences[sState.idx].answer);sState.answers[sState.idx]={text,ok};if(sState.idx<8){sState.idx++;localStorage.setItem(sKey,JSON.stringify(sState));renderFinalScreen();}else{sState.submitted=true;localStorage.setItem(sKey,JSON.stringify(sState));const st=sentenceStats(finalScreenSentences,sState.answers);series.lessons['4']={...(series.lessons['4']||{}),skill:'Writing',screening:{correct:st.correct,total:9,percent:st.percent},completed:false};saveSeries();renderFinalScreen();}}
