 const essayKey=BASE+'FinalEssay',prepKey=BASE+'FinalPrepNotes',essayStateKey=BASE+'FinalEssayState';const essay=$('#finalEssay'),notes=$('#finalPrepNotes');essay.value=localStorage.getItem(essayKey)||'';notes.value=localStorage.getItem(prepKey)||'';let eState=readJSON(essayStateKey,{phase:'ready',submitted:false});let essayStop=null;
