 function submitEssay(){if(eState.submitted)return;if(essayStop)essayStop();eState.submitted=true;eState.phase='submitted';localStorage.setItem(essayStateKey,JSON.stringify(eState));essay.disabled=true;$('#startFinalEssay').disabled=true;$('#startFinalEssay').textContent='ESSAY SUBMITTED';$('#finalEssayPhase').textContent='DONE';$('#finalEssayTimer').textContent='DONE';$('#finalEssayTopTimer').textContent='DONE';$('#finalEssayProgress').style.width='100%';$('#finalEssayInstruction').textContent='Essay submitted. Complete the trainer rubric below.';updateFinalCenter();}
