 const generalEssayTextKey=BASE+'GeneralEssayPractice',generalEssayRubricKey=BASE+'GeneralEssayRubric',generalTa=$('#generalEssayText');generalTa.value=localStorage.getItem(generalEssayTextKey)||'';
