// ---------- 4F PROFESSIONAL EMAIL TRANSFER ----------
if(page==='email'){
 const emailLabs=[
 {tab:'Request',title:'Ask a supplier for missing information.',bullets:['state which order/file you mean','explain what information is missing','give the deadline you need'],plan:['PO 4582 / revised quotation','delivery date + transport cost missing','send by 3 p.m. today'],a2:'Hello, I am writing about purchase order 4582. Thank you for sending the revised quotation. However, I cannot see the new delivery date or the transport cost in the document. Could you please send this information before 3 p.m. today? We need it to confirm the order with our finance team. Thank you for your help. Kind regards,',b2:'Hello, I’m writing regarding purchase order 4582 and the revised quotation you sent this morning. Thank you for the update. Before we can confirm the order internally, we still need the revised delivery date and the transport cost, as neither appears in the current document. Could you please send those details by 3 p.m. today? This would allow our finance team to complete the approval before the end of the day. Many thanks for your help. Kind regards,'},
 {tab:'Delay',title:'Inform a manager about a supplier delay.',bullets:['what happened','possible impact','recommended next action'],plan:['delivery +2 days','installation may move / client waiting','inform client + confirm revised date'],a2:'Hello, I’m writing to let you know that the supplier has confirmed a two-day delay on our delivery. The equipment will now arrive on Thursday instead of Tuesday. This may affect the installation planned for Wednesday and the client is waiting for an update. I recommend contacting the client today and explaining the new schedule. We should also ask the supplier to confirm the revised delivery time in writing. Kind regards,',b2:'Hello, I wanted to update you on the equipment delivery. The supplier has confirmed that transport problems will delay the shipment by two days, so it is now expected on Thursday rather than Tuesday. Unless we adjust the schedule, this could postpone Wednesday’s installation and leave the client without clear information. I recommend informing the client today, proposing a revised installation date and asking the supplier for written confirmation of the new delivery slot. This would allow us to manage expectations before the delay becomes a larger issue. Kind regards,'},
 {tab:'Follow-up',title:'Follow up after a meeting.',bullets:['summarize the decision','confirm responsibilities','state the next deadline'],plan:['pilot next Monday','I prepare guide / Sam trains team','comments Thursday / final Friday'],a2:'Hello everyone, Thank you for today’s meeting. We agreed to start the pilot next Monday. I will prepare the user guide, and Sam will organize the short training session for the team. Please send me any final comments by Thursday so I can complete the materials on Friday. I will then share the final version with everyone. Kind regards,',b2:'Hello everyone, Thank you for the productive meeting this morning. To confirm the main decisions, the pilot will begin next Monday. I will finalize the user guide, while Sam will prepare and deliver the short training session for the team. If you have any final comments or corrections, please send them to me by Thursday afternoon so that I can incorporate them before the materials are issued on Friday. I’ll circulate the final version as soon as it is ready. Kind regards,'},
 {tab:'Reschedule',title:'Reschedule a client meeting.',bullets:['explain why the time must change','offer two alternatives','ask the client to confirm'],plan:['transport problem','Thu 14:00 or Fri 10:30','confirm preferred slot'],a2:'Dear Ms Brown, I’m writing about our meeting scheduled for Thursday morning. Because of a transport problem, one of my colleagues will not arrive in time. Could we move the meeting to Thursday at 2 p.m. or Friday at 10:30 a.m.? Please let me know which time is better for you. I apologize for the change and thank you for your flexibility. Kind regards,',b2:'Dear Ms Brown, I’m contacting you regarding our meeting scheduled for Thursday morning. Unfortunately, a rail disruption means that one of the colleagues involved in the project will not be able to arrive in time. Would it be possible to reschedule the meeting for either Thursday at 2 p.m. or Friday at 10:30 a.m.? Please let me know which option is most convenient for you, and I will update the invitation immediately. I apologize for the inconvenience and appreciate your flexibility. Kind regards,'},
 {tab:'Complaint',title:'Respond to a customer complaint.',bullets:['acknowledge the problem','explain the immediate action','give the next update time'],plan:['apologize for missing delivery','investigate carrier + replacement option','update by 4 p.m.'],a2:'Dear Mr Lee, Thank you for contacting us. I am sorry that your delivery did not arrive as planned. We are checking the situation with the carrier now and we are also looking at a replacement delivery if necessary. I will send you another update by 4 p.m. today, even if we are still waiting for final confirmation. I apologize for the inconvenience and thank you for your patience. Kind regards,',b2:'Dear Mr Lee, Thank you for letting us know about the missing delivery. I’m very sorry that the order did not arrive as scheduled. We have contacted the carrier to locate the shipment and, at the same time, we are checking whether a replacement can be dispatched without further delay. I will update you again by 4 p.m. today with either the confirmed delivery status or the alternative solution. I appreciate the disruption this has caused and thank you for your patience while we resolve it. Kind regards,'}
 ];
 const notesKey=BASE+'EmailLabNotes',notes=readJSON(notesKey,{});let active=0;function renderEmailLab(){const item=emailLabs[active],box=$('#emailLab');$$('#emailTabs button').forEach((b,i)=>b.classList.toggle('active',i===active));const saved=notes[active]||{};box.innerHTML=`<div class="prompt-lab-head"><span>EMAIL SCENARIO ${active+1} / ${emailLabs.length}</span><h3>${item.title}</h3><ul>${item.bullets.map(x=>`<li>${x}</li>`).join('')}</ul></div><div class="plan-workbench"><div class="plan-steps"><label>PURPOSE<textarea data-email-field="purpose" placeholder="Why am I writing?">${saved.purpose||''}</textarea></label>${item.bullets.map((x,i)=>`<label>POINT ${i+1}<textarea data-email-field="b${i}" placeholder="Keyword content">${saved['b'+i]||''}</textarea></label>`).join('')}</div><div class="plan-actions"><button class="secondary" id="emailPlanModel" type="button">SHOW MODEL PLAN</button><button class="secondary" data-email-model="a2" type="button">A2–B1 EMAIL</button><button class="secondary" data-email-model="b2" type="button">B2–C1 EMAIL</button></div><div class="plan-model hidden" id="emailPlanOut"></div><div class="essay-model hidden" id="emailModelOut"></div></div>`;$$('[data-email-field]',box).forEach(el=>el.addEventListener('input',()=>{notes[active]??={};notes[active][el.dataset.emailField]=el.value;localStorage.setItem(notesKey,JSON.stringify(notes));}));$('#emailPlanModel').addEventListener('click',()=>{const out=$('#emailPlanOut');out.classList.toggle('hidden');out.textContent=`MODEL PLAN\nPurpose: ${item.title}\n• ${item.plan[0]}\n• ${item.plan[1]}\n• ${item.plan[2]}\nClosing action: make the next step clear.`;});$$('[data-email-model]',box).forEach(b=>b.addEventListener('click',()=>{const out=$('#emailModelOut');out.classList.remove('hidden');out.innerHTML=`<strong>${b.dataset.emailModel==='a2'?'A2–B1':'B2–C1'} MODEL EMAIL</strong><br>${b.dataset.emailModel==='a2'?item.a2:item.b2}`;}));}
 emailLabs.forEach((x,i)=>{const b=document.createElement('button');b.type='button';b.textContent=x.tab;b.addEventListener('click',()=>{active=i;renderEmailLab()});$('#emailTabs').appendChild(b)});renderEmailLab();
 const textKey=BASE+'EmailPractice',rubricKey=BASE+'EmailRubric',ta=$('#emailPracticeText');ta.value=localStorage.getItem(textKey)||'';function emailWords(){$('#emailWordCount').textContent=`${wordCount(ta.value)} words`;localStorage.setItem(textKey,ta.value);}ta.addEventListener('input',emailWords);emailWords();$('#startEmailTimer').addEventListener('click',()=>countdown('emailTimer',900));let r={};r=buildRubric('#emailRubric',rubricKey,()=>updateEmail());function updateEmail(){r=readJSON(rubricKey,{});const st=rubricStats(r);$('#emailScore').textContent=`${st.sum}/25`;$('#emailPercent').textContent=`${st.percent}%`;$('#emailTitle').textContent=st.complete?(st.percent>=80?'Strong professional email control.':'Review the weakest criterion and rewrite the message.'):'Complete all five rubric criteria.';$('#emailText').textContent=`Word count: ${wordCount(ta.value)}. Rubric criteria scored: ${Object.keys(r).length}/5. This is supplementary transfer practice.`;}updateEmail();$('#downloadResults').addEventListener('click',()=>{const st=rubricStats(readJSON(rubricKey,{}));download('vtest_4F_email_transfer.txt',`PROFESSIONAL EMAIL TRANSFER PRACTICE\n\nWords: ${wordCount(ta.value)}\nTrainer rubric: ${st.sum}/25 (${st.percent}%)\n\nSupplementary practice — not a standalone official task in the current VTest Business English candidate guide.`)});$('#resetBtn').addEventListener('click',()=>{if(confirm('Reset email transfer practice?')){[notesKey,textKey,rubricKey,sectionKey].forEach(k=>localStorage.removeItem(k));location.reload();}});
}

// Additional guided grammar and CEFR model workshop (independent of existing assessment).
(function(){if(document.body.dataset.page!=='essay')return;const qs=[['The meeting ___ moved to Friday.',['was','were','did'],'was','Meeting is singular; past passive = was + moved.'],['The report should ___ completed today.',['be','is','to be'],'be','After should: be + past participle.'],['___ the delay, we finished on time.',['Despite','Although','However'],'Despite','Despite + noun; although + clause.'],['She ___ explain the procedure.',['should','shoulds','should to'],'should','Modal + base verb; never shoulds or should to.'],['The problem ___ resolved yesterday.',['was','has','is being'],'was','Yesterday is a finished past time; past simple passive.']];const box=document.getElementById('grammarChecks');if(!box)return;function render(){box.innerHTML='';qs.forEach((q,i)=>{let d=document.createElement('div');d.className='q-card';d.innerHTML='<h4>'+(i+1)+'. '+q[0]+'</h4>';q[1].forEach(a=>{let b=document.createElement('button');b.type='button';b.className='option-btn';b.textContent=a;b.onclick=()=>{d.querySelectorAll('button').forEach(x=>{x.disabled=true;x.classList.toggle('correct-choice',x.textContent===q[2]);x.classList.toggle('wrong-choice',x===b&&a!==q[2])});let f=document.createElement('div');f.className='feedback '+(a===q[2]?'correct':'incorrect');f.textContent=(a===q[2]?'Correct. ':'Try again next time. ')+q[3];d.appendChild(f)};d.appendChild(b)});box.appendChild(d)})}render();document.getElementById('grammarReset').onclick=render;const models={a2:['New employees sometimes have problems in their first week. They do not know the office or the people. I think the company should give them a guide. The guide can explain the rules and the working hours. Managers should meet new employees every day and answer their questions. This can help them feel happy and safe.','A2: short clear sentences; simple problem, resource and manager support.'],b1:['Starting a new job can be stressful because employees may not understand the company’s procedures. To solve this problem, I would recommend giving each new employee a welcome guide with useful contacts and a simple schedule. For example, the guide could explain how to request IT support. Managers should also arrange a short meeting each morning during the first week. As a result, employees could ask questions early and become more confident in their new roles.','B1: explains why, includes a concrete example and a result; uses because, for example, should and could.'],b2:['A common difficulty during the first week is that new employees receive too much information without knowing which tasks to prioritize. To address this, the company could provide a structured onboarding checklist, supported by short practical demonstrations. For instance, essential IT access could be arranged before the employee arrives, allowing them to contribute from day one. Managers should schedule regular check-ins and encourage questions rather than assume that instructions have been understood. This approach would reduce uncertainty while helping new colleagues become productive more quickly.','B2: precise problem, practical sequencing, varied links, natural passive voice and well-developed impact.'],c1:['An effective onboarding process should do more than introduce company policies: it should enable new colleagues to contribute confidently without feeling overwhelmed. One recurring obstacle is the lack of clarity surrounding priorities, particularly when information is delivered all at once. A phased induction programme, combining a concise digital handbook with task-specific demonstrations, would address this issue. Essential accounts should be activated before arrival, while less urgent procedures could be introduced progressively. Equally important is the manager’s role: brief, purposeful check-ins would provide opportunities to clarify expectations and identify concerns early. By balancing structured resources with individual support, the organization could improve both employee confidence and the consistency of the onboarding experience.','C1: nuanced argument, selective passive, varied structures and concise synthesis. Complexity is useful only when controlled.']};let t=document.getElementById('levelModelText'),w=document.getElementById('levelModelWhy');document.querySelectorAll('#levelModels button').forEach(b=>b.onclick=()=>{document.querySelectorAll('#levelModels button').forEach(x=>x.classList.toggle('active',x===b));t.textContent=models[b.dataset.level][0];w.textContent=models[b.dataset.level][1]});document.querySelector('#levelModels button[data-level="a2"]').click();let up=document.getElementById('upgradeText');up.value=localStorage.getItem('vtest_grammar_upgrade')||'';up.addEventListener('input',()=>localStorage.setItem('vtest_grammar_upgrade',up.value));})();


/* Consistent Writing Masterclass on all six lesson pages; isolated to avoid changing original test engine. */
(function(){
 function initMasterclass(){
  const el=document.querySelector('.writing-upgrade');if(!el)return;
  const page=document.body.dataset.page||location.pathname;
  const key='vtest-writing-masterclass-'+page;
  let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){}
  const draft=el.querySelector('.upgrade-draft'),notes=el.querySelector('.upgrade-notes'),url=el.querySelector('.upgrade-url');
  draft.value=saved.draft||'';notes.value=saved.notes||'';url.value=saved.url||'';
  const persist=()=>{try{localStorage.setItem(key,JSON.stringify({draft:draft.value,notes:notes.value,url:url.value,checks:[...el.querySelectorAll('.upgrade-quiz')].map(q=>q.dataset.done==='1')}))}catch(e){}};
  [draft,notes,url].forEach(x=>x.addEventListener('input',persist));
  el.querySelectorAll('.upgrade-quiz').forEach((q,i)=>{
   const feedback=q.querySelector('.upgrade-feedback');
   q.querySelector('.upgrade-check').addEventListener('click',()=>{
    const selected=q.querySelector('input:checked');
    if(!selected){feedback.textContent='Choose an answer first, then press Check answer & explain.';feedback.dataset.state='empty';return}
    const ok=Number(selected.value)===Number(q.dataset.answer);
    feedback.textContent=(ok?'✓ Correct. ':'✗ Not yet. ')+q.dataset.why;
    feedback.dataset.state=ok?'correct':'incorrect';q.dataset.done=ok?'1':'0';persist();
   });
   if(saved.checks?.[i]){q.dataset.done='1';feedback.textContent='✓ Previously completed. You can try again or reveal the next rule.';feedback.dataset.state='correct'}
  });
  el.querySelector('.upgrade-selfcheck').addEventListener('click',()=>{
   const txt=draft.value.trim();const words=txt?txt.split(/\s+/).length:0;
   const links=(txt.match(/\b(because|however|although|for example|for instance|therefore|as a result|so|moreover|first|finally)\b/gi)||[]).length;
   el.querySelector('.upgrade-draft-feedback').textContent=`${words} words · ${links} linking expression(s) found. ${words<45?'Develop your point, reason, example and result. ':'Review whether every prompt bullet has been answered. '}Check verb forms, punctuation and whether passive voice is useful. This is a structural check only—not a grammar correction or official score.`;
  });
  el.querySelector('.upgrade-clear').addEventListener('click',()=>{if(!confirm('Clear this writing draft?'))return;draft.value='';persist();el.querySelector('.upgrade-draft-feedback').textContent='Draft cleared. Trainer notes were kept.'});
  el.querySelector('.upgrade-export').addEventListener('click',async()=>{
   const count=[...el.querySelectorAll('.upgrade-quiz')].filter(x=>x.dataset.done==='1').length;
   const row=['Writing','Masterclass · '+page,'Eight grammar rules; CEFR models; writing upgrade','Multiple choice + written draft',count+'/8 rules', 'Grammar; writing; organisation; self-correction',notes.value||'Review learner draft',url.value].map(x=>'"'+String(x).replace(/"/g,'""')+'"').join('\t');
   const status=el.querySelector('.upgrade-export-status');
   try{await navigator.clipboard.writeText(row);status.textContent='Centre tracking line copied (tab-separated).'}catch(e){const ta=document.createElement('textarea');ta.value=row;ta.style.width='100%';status.replaceChildren(ta);ta.select();status.insertAdjacentText('beforeend',' Copy the selected line.');}
  });
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initMasterclass);else initMasterclass();
})();
